def hydrate_time(nanoseconds, tz=None):
    """
    Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Number of nanoseconds since midnight (int).
    :param tz: Optional timezone information. Can be a datetime.tzinfo instance or a string offset like '+02:00'.
    :return: datetime.time object representing the time of day.
    """
    # Import datetime inside the function to avoid top-level imports
    import datetime

    # Validate nanoseconds
    if nanoseconds is None:
        raise TypeError("nanoseconds must not be None")
    if not isinstance(nanoseconds, int):
        try:
            nanoseconds = int(nanoseconds)
        except Exception as exc:
            raise TypeError("nanoseconds must be an integer") from exc

    # Normalize nanoseconds to a value within a single day
    ns_per_day = 86400 * 1_000_000_000
    nanoseconds = nanoseconds % ns_per_day

    # Compute components
    total_seconds = nanoseconds // 1_000_000_000
    remaining_ns = nanoseconds % 1_000_000_000
    microseconds = remaining_ns // 1_000

    hour = total_seconds // 3600
    minute = (total_seconds % 3600) // 60
    second = total_seconds % 60

    # Resolve timezone
    tzinfo = None
    if tz is not None:
        if isinstance(tz, datetime.tzinfo):
            tzinfo = tz
        elif isinstance(tz, str):
            # Attempt to parse string offsets like '+02:00' or '-05:30'
            try:
                if tz.startswith(('+', '-')) and len(tz) in (6, 7):
                    sign = 1 if tz[0] == '+' else -1
                    parts = tz[1:].split(':')
                    if len(parts) == 2:
                        hours = int(parts[0])
                        minutes = int(parts[1])
                        offset = datetime.timedelta(hours=hours, minutes=minutes) * sign
                        tzinfo = datetime.timezone(offset)
                    else:
                        raise ValueError
                else:
                    raise ValueError
            except Exception as exc:
                raise ValueError(f"Invalid timezone string: {tz}") from exc
        else:
            raise TypeError("tz must be a datetime.tzinfo instance or a string offset")

    # Construct and return the time object
    return datetime.time(hour, minute, second, microseconds, tzinfo=tzinfo)

