def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    if self is None:
        raise ValueError("Instance is None")
    try:
        # If the instance has a 'data' attribute that is a dict
        if hasattr(self, 'data') and isinstance(self.data, dict):
            return list(self.data.keys())
        # If the instance has a 'record' attribute that is a dict
        if hasattr(self, 'record') and isinstance(self.record, dict):
            return list(self.record.keys())
        # If the instance itself is a dict-like object
