@classmethod
    def _reset_logging(cls):
        """
        Reset the logging configuration to its default state.
        """
        # Attempt to import the logging module without using a top-level import statement
        try:
            logging = __import__('logging')
        except Exception:
            # If logging is not available, nothing to reset
            return

        try:
            # Shut down the current logging system to close all handlers
            logging.shutdown()
            # Reinitialize the root logger
            root = logging.getLogger()
            # Remove any existing handlers
            if hasattr(root, 'handlers'):
                try:
                    root.handlers.clear()
                except Exception:
                    root.handlers = []
            # Reset the root logger level to INFO (default)
            root.setLevel(logging.INFO)
            # Ensure a default handler is configured
            logging.basicConfig(level=logging.INFO)
        except Exception:
            # Silently ignore any errors during reset
            pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        cls_name = self.__class__.__name__
    except Exception:
        return None
    if cls_name.endswith('Py'):
        return cls_name[:-2]
    if cls_name.endswith('Fallback'):
        return cls_name[:-9]
    return cls_name

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean")
    result = {}
    cls = self.__class__
    for name in dir(cls):
        try:
            attr = getattr(cls, name)
        except Exception:
            continue
        if isinstance(attr, property):
            if not all and name not in cls.__dict__:
                continue
            try:
                desc = attr.fget.__doc__ if attr.fget else None
            except Exception:
                desc = None
            result[name] = desc
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("`all` must be a boolean value")

    cls = self.__class__
    interface_names = []

    # Attempt to retrieve interface definition from the class
    if hasattr(cls, "__interface__"):
        interface_attr = getattr(cls, "__interface__")
        if isinstance(interface_attr, (list, tuple, set)):
            interface_names = list(interface_attr)
        elif isinstance(interface_attr, dict):
            interface_names = list(interface_attr.keys())
        else:
            # If it's a callable that returns names
            try:
                interface_names = list(interface_attr())
            except Exception:
                interface_names = []

    # Fallback: use non-callable, non-private attributes defined on the class
    if not interface_names:
        interface_names = [
            name
            for name, value in cls.__dict__.items()
            if not name.startswith("_") and not callable(value)
        ]

    # Ensure all names are strings and unique
    interface_names = [name for name in interface_names if isinstance(name, str)]
    interface_names = list(dict.fromkeys(interface_names))

    if all:
        # Include all non-private, non-callable attributes defined on the class
        all_names = [
            name
            for name, value in cls.__dict__.items()
            if not name.startswith("_") and not callable(value)
        ]
        all_names = [name for name in all_names if isinstance(name, str)]
        # Merge while preserving order and uniqueness
        result = list(dict.fromkeys(all_names))
    else:
        result = interface_names

    return result

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    # Ensure output is a list
    if output is None:
        output = []
    elif not isinstance(output, list):
        raise TypeError(f"output must be a list, got {type(output).__name__}")

    # Helper to process a single item
    def _process(item):
        # Skip None values
        if item is None:
            return

        # Treat tuples as implements specs (do not expand)
        if isinstance(item, tuple):
            output.append(item)
            return

        # If the item has a 'declarations' or 'args' attribute, expand it
        if hasattr(item, "declarations"):
            try:
                _normalizeargs(item.declarations, output)
            except Exception as exc:
                raise ValueError(f"Failed to expand 'declarations' of {item!r}") from exc
            return
        if hasattr(item, "args"):
            try:
                _normalizeargs(item.args, output)
            except Exception as exc:
                raise ValueError(f"Failed to expand 'args' of {item!r}") from exc
            return

        # If the item is an iterable (but not a string/bytes), expand it
        if isinstance(item, (list, set, tuple)):
            # Note: tuples are already handled above, but this covers other iterables
            for sub in item:
                _process(sub)
            return

        # If the item is a string or a type, treat it as an interface
        if isinstance(item, (str, type)):
            output.append(item)
            return

        # For any other type, attempt to iterate over it
        try:
            iter(item)
        except TypeError:
            # Not iterable, treat as interface
            output.append(item)
            return
        else:
            # Iterable but not a string/bytes, expand it
            for sub in item:
                _process(sub)

    # If the top-level sequence is not iterable, treat it as a single item
    if sequence is None:
        return output
    try:
        iter(sequence)
    except TypeError:
        _process(sequence)
    else:
        # If it's a tuple, treat as implements spec
        if isinstance(sequence, tuple):
            output.append(sequence)
        else:
            for elem in sequence:
                _process(elem)

    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        return not _c_optimizations_required()
    except Exception:
        # If the required function is not available or raises an error,
        # default to False (i.e., optimizations are not ignored).
        return False

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is truthy, we are running in pure Python mode and
        # C optimizations are not required. Otherwise, they are required.
        return not bool(PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are needed.
        return True
    except Exception:
        # Any other unexpected error should default to requiring C optimizations.
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset the context
        self.context = {}

        # Reinitialize bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the existing number of bins if possible
            if hasattr(self, "bins") and isinstance(self.bins, list):
                self.bins = [self.initial_value] * len(self.bins)
            else:
                # If bins were not previously defined, create a single bin
                self.bins = [self.initial_value]
        else:
            # Fall back to the make_bins callable if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If no make_bins method, default to an empty list
                self.bins = []

    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc
    return None

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []

    # Add header if provided
    if header is not None:
        lines.append(header)

    # Try to get an iterable of points
    try:
        points_iter = iter(self.points)
    except AttributeError:
        try:
            points_iter = iter(self)
        except TypeError:
            raise TypeError("object has no points to iterate over")

    for point in points_iter:
        # Each point should be a (coordinate, value) pair
        try:
            coord, value = point
        except Exception:
            # Skip malformed points
            continue

        parts = []

        # Process coordinate
        if isinstance(coord, (list, tuple)):
            parts.extend(str(c) for c in coord)
        else:
            parts.append(str(coord))

        # Process value
        if isinstance(value, (list, tuple)):
            parts.extend(str(v) for v in value)
        else:
            parts.append(str(value))

        # Join parts with separator
        lines.append(separator.join(parts))

    # Return joined lines; if no lines, return empty string
    return "\n".join(lines) if lines else ""

