def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    spec = getattr(app, "spec", None)
    if spec is None:
        raise ValueError("The application must have a 'spec' attribute.")
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise ValueError("The application spec must contain a 'manifest' attribute.")
    if not isinstance(manifest, list):
        raise ValueError("The 'manifest' attribute must be a list of resources.")

    # Existing custom observer schemas, if any
    existing_schema = getattr(spec, "observer_schema", {})
    if existing_schema is None:
        existing_schema = {}
    if not isinstance(existing_schema, dict):
        raise ValueError("The 'observer_schema' attribute must be a dict if present.")

    default_schema = {}
    for resource in manifest:
        # Skip non-dict resources
        if not isinstance(resource, dict):
            continue

        metadata = resource.get("metadata", {})
        if not isinstance(metadata, dict):
            continue

        name = metadata.get("name")
        if not isinstance(name, str) or not name:
            continue

        # Skip resources that already have a custom observer schema
        if name in existing_schema:
            continue

        # Build a simple default schema
        schema = {
            "metadata": {
                "name": {"type": "string"},
                "namespace": {"type": "string"},
                "labels": {"type": "object"},
                "annotations": {"type": "object"},
            },
            "spec": {"type": "object"},
            "status": {"type": "object"},
        }
        default_schema[name] = schema

    return default_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if path is None:
            return False
        # Convert to Path object
        from pathlib import Path
        p = Path(path)
        if not p.exists() or not p.is_dir():
            return False

        # Check for .ocfl_version file
        ocfl_version_file = p / ".ocfl_version"
        if not ocfl_version_file.is_file():
            return False
        try:
            version_text = ocfl_version_file.read_text().strip()
            if not version_text:
                return False
            # Basic numeric check
            float(version_text)
        except Exception:
            return False

        # Check for .ocfl_root file
        ocfl_root_file = p / ".ocfl_root"
        if not ocfl_root_file.is_file():
            return False
        try:
            root_path_text = ocfl_root_file.read_text().strip()
            if not root_path_text:
                return False
            root_path = p / root_path_text
            if not root_path.is_dir():
                return False
        except Exception:
            return False

        # Ensure root contains an 'objects' directory
        objects_dir = root_path / "objects"
        if not objects_dir.is_dir():
            return False

        # Optional: warn if any object lacks a manifest.json
        for obj_dir in objects_dir.iterdir():
            if obj_dir.is_dir():
                manifest_file = obj_dir / "manifest.json"
                if not manifest_file.is_file():
                    import warnings
                    warnings.warn(f"Missing manifest.json in object {obj_dir}")

        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Retrieve the log attribute, if present
        log = getattr(self, 'log', None)
        if log is None:
            log = getattr(self, 'validation_log', None)
        if log is None:
            return ''

        # Normalise prefix
        if prefix is None:
            prefix = ''

        # Handle string logs
        if isinstance(log, str):
            return f"{prefix}{log}" if log else ''

        # Handle dictionary logs
        if isinstance(log, dict):
            if not log:
                return ''
            parts = [f"{k}: {v}" for k, v in log.items()]
            return f"{prefix}{'\n'.join(parts)}"

        # Handle iterable logs (lists, tuples, sets, etc.)
        if hasattr(log, '__iter__') and not isinstance(log, (bytes, bytearray)):
            parts = []
            for item in log:
                if isinstance(item, str):
                    parts.append(item)
                else:
                    try:
                        parts.append(str(item))
                    except Exception:
                        parts.append(repr(item))
            if not parts:
                return ''
            return f"{prefix}{'\n'.join(parts)}"

        # Fallback for any other type
        return f"{prefix}{str(log)}" if log else ''
    except Exception:
        # In case of any unexpected error, return an empty string
        return ''

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type check
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary.")

        # Determine spec version if requested
        if extract_spec_version:
            type_value = inventory.get("type")
            # Map known type values to spec versions
            type_to_version = {
                "inventory_v1": "v1",
                "inventory_v2": "v2",
                "inventory_v3": "v3",
            }
            if isinstance(type_value, str) and type_value in type_to_version:
                self.spec_version = type_to_version[type_value]
            # If type is missing or unrecognized, keep existing spec_version

        # Ensure we have a spec_version to work with
        spec_version = getattr(self, "spec_version", None)
        if spec_version is None:
            raise ValueError("Specification version is not set and could not be inferred from inventory type.")

        # Common required keys
        required_keys = ["name", "items"]
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"Missing required key '{key}' in inventory.")

        # Validate 'name'
        if not isinstance(inventory["name"], str):
            raise ValueError("Inventory 'name' must be a string.")

        # Validate 'items'
        items = inventory["items"]
        if not isinstance(items, list):
            raise ValueError("Inventory 'items' must be a list.")

        # Validate each item based on spec_version
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                raise ValueError(f"Item at index {idx} is not a dictionary.")
            # Common required fields for all versions
            for field in ["id", "value"]:
                if field not in item:
                    raise ValueError(f"Item at index {idx} missing required field '{field}'.")
            if not isinstance(item["id"], int):
                raise ValueError(f"Item at index {idx} has 'id' that is not an integer.")
            if not isinstance(item["value"], str):
                raise ValueError(f"Item at index {idx} has 'value' that is not a string.")

            # Version-specific checks
            if spec_version == "v2":
                if "metadata" not in item:
                    raise ValueError(f"Item at index {idx} missing required field 'metadata' for spec_version v2.")
                if not isinstance(item["metadata"], dict):
                    raise ValueError(f"Item at index {idx} has 'metadata' that is not a dictionary.")
            elif spec_version == "v3":
                # Example: v3 requires an additional 'timestamp' field
                if "timestamp" not in item:
                    raise ValueError(f"Item at index {idx} missing required field 'timestamp' for spec_version v3.")
                if not isinstance(item["timestamp"], (int, float)):
                    raise ValueError(f"Item at index {idx} has 'timestamp' that is not a number.")
            elif spec_version != "v1":
                # Unknown spec_version
                raise ValueError(f"Unsupported specification version: {spec_version}")

        # If all checks pass
        return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an InventoryValidator instance")

    # Required attributes that must exist on both objects
    required_attrs = ("inventory_id", "version", "timestamp")
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"current inventory missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"prior inventory missing required attribute '{attr}'")

    # Inventory IDs must match
    if getattr(self, "inventory_id") != getattr(prior, "inventory_id"):
        raise ValueError("prior inventory_id does not match current inventory_id")

    # Prior version must be strictly less than current version
    if getattr(prior, "version") >= getattr(self, "version"):
        raise ValueError("prior version must be less than current version")

    # Prior timestamp must be earlier than current timestamp
    if getattr(prior, "timestamp") >= getattr(self, "timestamp"):
        raise ValueError("prior timestamp must be earlier than current timestamp")

    # Optional: ensure prior items are a subset of current items
    if hasattr(self, "items") and hasattr(prior, "items"):
        try:
            current_items = set(self.items)
            prior_items = set(prior.items)
        except TypeError:
            # Items are not hashable; skip subset check
            pass
        else:
            if not prior_items.issubset(current_items):
                raise ValueError("prior items are not a subset of current items")

    # If all checks pass, simply return None (validation succeeded)

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory
    if inventory is None:
        raise ValueError("inventory cannot be None")

    # Determine the list of versions
    if isinstance(inventory, dict):
        versions = inventory.get("versions")
        if versions is None:
            # maybe inventory itself is a list of versions
            versions = inventory
    else:
        versions = inventory

    if not isinstance(versions, (list, tuple)):
        raise TypeError("inventory must contain a list of versions")

    # Find the index of the requested version
    target_index = None
    for idx, ver in enumerate(versions):
        if not isinstance(ver, dict):
            continue
        # Try common keys for version identification
        if "number" in ver and ver["number"] == version:
            target_index = idx
            break
        if "id" in ver and ver["id"] == version:
            target_index = idx
            break
        if "name" in ver and ver["name"] == version:
            target_index = idx
            break
        # If version is an integer and ver itself is an integer
        if isinstance(ver, int) and ver == version:
            target_index = idx
            break

    if target_index is None:
        raise ValueError(f"Version {version} not found in inventory")

    # Build the mapping
    logical_path_map = {}
    for ver in versions[target_index:]:
        if not isinstance(ver, dict):
            continue
        files = ver.get("files")
        if not isinstance(files, dict):
            continue
        for logical_path, content_file in files.items():
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            # content_file might be a list or a single string
            if isinstance(content_file, (list, tuple)):
                logical_path_map[logical_path].update(content_file)
            else:
                logical_path_map[logical_path].add(content_file)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure fixity is a dictionary
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary.")
        # Must contain a 'files' key
        if "files" not in fixity:
            raise ValueError("Fixity block missing required 'files' key.")
        files = fixity["files"]
        if not isinstance(files, list):
            raise ValueError("'files' in fixity block must be a list.")
        # Convert manifest_files to a set for fast lookup
        try:
            manifest_set = set(manifest_files or [])
        except Exception as exc:
            raise ValueError("manifest_files must be an iterable of file paths.") from exc
        # Validate each file entry
        for idx, entry in enumerate(files):
            if not isinstance(entry, dict):
                raise ValueError(f"File entry at index {idx} must be a dictionary.")
            if "path" not in entry:
                raise ValueError(f"File entry at index {idx} missing required 'path' key.")
            path = entry["path"]
            if not isinstance(path, str):
                raise ValueError(f"File path at index {idx} must be a string.")
            if path not in manifest_set:
                raise ValueError(f"Fixity references unknown file: {path}")
        # If all checks pass, return True
        return True

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from XML basename to a list of file paths that share that basename.
    """
    try:
        # Validate input
        if not isinstance(folder, str):
            raise TypeError("folder must be a string path")
        os = __import__('os')
        if not os.path.isdir(folder):
            raise FileNotFoundError(f"Folder not found: {folder}")

        # List all files in the folder (ignore subdirectories)
        all_entries = os.listdir(folder)
        xml_basenames = set()
        for entry in all_entries:
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path) and entry.lower().endswith('.xml'):
                basename, _ = os.path.splitext(entry)
                xml_basenames.add(basename)

        # Group files by basename
        grouped = {}
        for basename in xml_basenames:
            group_files = []
            for entry in all_entries:
                full_path = os.path.join(folder, entry)
                if os.path.isfile(full_path):
                    name, _ = os.path.splitext(entry)
                    if name == basename:
                        group_files.append(full_path)
            if group_files:
                grouped[basename] = group_files

        return grouped
    except Exception as exc:
        # In case of any error, return an empty dict to avoid breaking callers
        return {}

