def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Try to import importlib.metadata (Python 3.8+)
        try:
            from importlib.metadata import version, PackageNotFoundError
        except ImportError:
            # Fallback to pkg_resources if available
            try:
                import pkg_resources

                def version(name):
                    return pkg_resources.get_distribution(name).version

                class PackageNotFoundError(Exception):
                    pass
            except ImportError:
                # No metadata tools available
                return {"version": "0.0.0", "error": "no metadata available"}

        # Determine the package name from the current module context
        pkg_name = __package__ or __name__
        if pkg_name == "__main__":
            pkg_name = None

        if pkg_name:
            # If the package name contains dots, take the top-level package
            pkg_name = pkg_name.split(".")[0]
            try:
                ver = version(pkg_name)
                return {"version": ver}
            except PackageNotFoundError:
                pass

        # Attempt to read a VERSION file in the current working directory
        import os

        if os.path.isfile("VERSION"):
            with open("VERSION", "r", encoding="utf-8") as f:
                return {"version": f.read().strip()}

        # Default fallback
        return {"version": "0.0.0"}
    except Exception as exc:
        # Catch any unexpected errors and return a safe default
        return {"version": "0.0.0", "error": str(exc)}

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Handle None explicitly
    if pieces is None:
        return '+'
    # If pieces is a string, check directly
    if isinstance(pieces, str):
        return '.' if '+' in pieces else '+'
    # For other iterables, iterate and look for a '+'
    try:
        for element in pieces:
            # Direct match
            if element == '+':
                return '.'
            # If element is a string, check if it contains '+'
            if isinstance(element, str) and '+' in element:
                return '.'
        # No '+' found
        return '+'
    except TypeError:
        # pieces is not iterable
        raise TypeError("pieces must be an iterable or string")

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        if parser is None:
            raise TypeError("parser is None")
        actions = getattr(parser, "_actions", None)
        if actions is None:
            raise TypeError("parser does not have _actions attribute")
        flags = []
        for action in actions:
            opt_strings = getattr(action, "option_strings", None)
            if opt_strings:
                for opt in opt_strings:
                    if isinstance(opt, str):
                        flags.append(opt)
        return " ".join(flags)
    except Exception as e:
        raise ValueError(f"Error parsing flags: {e}") from e

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    if parser is None:
        raise ValueError("parser cannot be None")
    # Basic check for an ArgumentParser-like object without importing argparse
    if not hasattr(parser, "add_argument") or not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    try:
        for action in parser._actions:
            # Some actions may not have option_strings (e.g., positional arguments)
            if hasattr(action, "option_strings"):
                flags.extend(action.option_strings)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc
    return " ".join(flags)

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    # Attempt to import the parser factory from borgmatic
    try:
        from borgmatic.cli import get_parser
    except Exception:
        # If we cannot import borgmatic or the parser factory, return an empty script
        return ''
    # Try to obtain the top-level argparse parser
    try:
        parser = get_parser()
    except Exception:
        return ''
    # Try to import argcomplete's bash_completion helper
    try:
        from argcomplete.completer import bash_completion
    except Exception:
        # If argcomplete is not available, return an empty script
        return ''
    # Generate the bash completion script using argcomplete
    try:
        return bash_completion(parser)
    except Exception:
        return ''

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("dicts must be an iterable of dictionaries")
    result = {}
    try:
        for d in dicts:
            if not isinstance(d, dict):
                raise TypeError(f"Expected dict, got {type(d).__name__}")
            for key, value in d.items():
                if key in result:
                    result[key] += value
                else:
                    result[key] = value
    except TypeError as exc:
        raise exc
    return result

