    """
    # Validate inputs
    if string is None:
        raise TypeError("string must not be None")
    if alphabet is None:
        raise TypeError("alphabet must not be None")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if len(alphabet) == 0:
        raise ValueError("alphabet must contain at least one character")

    # Build mapping from character to its numeric value
    mapping = {}
    for idx, char in enumerate(alphabet):
        if not isinstance(char, str):
            raise TypeError(f"Alphabet element at index {idx} is not a string")
        if len(char) != 1:
            raise ValueError(f"Alphabet element '{char}' at index {idx} is not a single character")
        if char in mapping:
            raise ValueError(f"Duplicate character '{char}' found in alphabet")
        mapping[char] = idx

    base = len(alphabet)
    result = 0
    for pos, ch in enumerate(string):
        if ch not in mapping:
            raise ValueError(f"Character '{ch}' at position {pos} not found in alphabet")
        result = result * base + mapping[ch]

    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems including macOS
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # os.uname() not available (e.g., on Windows). Fall back to platform module.
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            # If any error occurs, assume not macOS
            return False
    except Exception:
        # Any other unexpected error: assume not macOS
        return False

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    # Define supported file extensions (case-insensitive)
    supported_exts = {
        ".txt", ".md", ".rst", ".csv", ".json", ".xml",
        ".yaml", ".yml", ".ini", ".conf", ".properties",
        ".log", ".txt", ".py", ".c", ".cpp", ".java",
        ".js", ".ts", ".html", ".css", ".scss", ".less",
        ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tiff",
    }

    try:
        # Accept string or pathlib.Path-like objects
        if filename is None:
            return False
        if not isinstance(filename, (str, bytes)):
            return False
        # Convert bytes to str if necessary
        if isinstance(filename, bytes):
            try:
                filename = filename.decode()
            except Exception:
                return False
        # Extract extension
        _, ext = os.path.splitext(filename)
        if not ext:
            return False
        return ext.lower() in supported_exts
    except Exception:
        # In case of any unexpected error, return False
        return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # Quick checks for common localhost representations
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1" or host == "::1":
        return True

    try:
        # Resolve the host to all possible addresses
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1":
                    return True
    except (socket.gaierror, socket.herror, socket.error):
        # If the host cannot be resolved, treat it as non-local
        return False

    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int) or not (0 <= mode <= 0o777):
        raise ValueError("mode must be an integer between 0 and 0o777")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Resolve absolute path
    config_path = os.path.abspath(config_filename)

    # If the path points to an existing directory, raise error
    if os.path.isdir(config_path):
        raise IsADirectoryError(f"'{config_path}' is a directory")

    # Check for existing file
    if os.path.exists(config_path) and not overwrite:
        raise FileExistsError(f"File '{config_path}' already exists and overwrite is False")

    # Ensure parent directories exist
    parent_dir = os.path.dirname(config_path)
    if parent_dir and not os.path.exists(parent_dir):
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(f"Failed to create directories '{parent_dir}': {exc}") from exc

    # Write the file
    try:
        with open(config_path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        # Set file permissions
        os.chmod(config_path, mode)
    except OSError as exc:
        raise RuntimeError(f"Failed to write configuration to '{config_path}': {exc}") from exc
    return None

def is_ipv4(target):
    """Test if IPv4 address or not

    Returns:
        bool: True if target is a valid IPv4 address, False otherwise.
    """
    # Handle None or non-string inputs gracefully
    if target is None:
        return False
    # If it's already an IPv4Address instance, it's valid
    if isinstance(target, ipaddress.IPv4Address):
        return True
    # If it's an IPv6Address instance, it's not IPv4
    if isinstance(target, ipaddress.IPv6Address):
        return False
    try:
        # Attempt to create an IPv4Address; this will raise ValueError if invalid
        ipaddress.IPv4Address(target)
        return True
    except (ValueError, TypeError):
        return False

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or list
        shape of the array to create
    dtype : `numpy.dtype` or convertible to dtype
        data-type of the array to create

    Returns
    -------
    numpy.ndarray
        An array of the specified shape and dtype.
    """
    # Validate and normalize shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError("shape must be a tuple or list of integers")
    try:
        shape_tuple = tuple(int(dim) for dim in shape)
    except Exception as exc:
        raise ValueError(f"All dimensions in shape must be integers: {exc}") from exc
    if any(dim < 0 for dim in shape_tuple):
        raise ValueError("All dimensions in shape must be non-negative")

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype: {exc}") from exc

    # Create and return the array
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array: {exc}") from exc

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import json
    import os
    import re
    import logging

    # Validate inputs
    if config_filenames is None:
        config_filenames = []
    try:
        filenames = list(config_filenames)
    except TypeError:
        raise TypeError("config_filenames must be an iterable of filenames")

    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError("overrides must be a dict or None")

    configs = {}
    error_records = []

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_in_value(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            return env_pattern.sub(repl, value)
        return value

    def resolve_env_in_obj(obj):
        if isinstance(obj, dict):
            return {k: resolve_env_in_obj(resolve_env_in_value(v)) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [resolve_env_in_obj(resolve_env_in_value(v)) for v in obj]
        else:
            return resolve_env_in_value(obj)

    for filename in filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            try:
                parsed = json.loads(content)
            except json.JSONDecodeError as e:
                msg = f"JSON decode error in file '{filename}': {e}"
                record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
                error_records.append(record)
                continue
            if not isinstance(parsed, dict):
                msg = f"Configuration in file '{filename}' is not a JSON object"
                record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
                error_records.append(record)
                continue
            # Apply overrides
            if overrides:
                parsed.update(overrides)
            # Resolve environment variables
            if resolve_env:
                parsed = resolve_env_in_obj(parsed)
            configs[filename] = parsed
        except FileNotFoundError:
            msg = f"Configuration file not found: '{filename}'"
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
            error_records.append(record)
        except Exception as exc:
            msg = f"Unexpected error loading file '{filename}': {exc}"
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
            error_records.append(record)

    return configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    # If the object is a string (including numpy.str_ which subclasses str),
    # encode it to UTF-8 bytes.  For any other type, return the object unchanged.
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except Exception as exc:
            raise ValueError(f"Failed to encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Validate the input
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    # Retrieve the mapping of handlers; use a safe default if not defined
    handlers = getattr(cls, "_protocol_handlers", None)
    if handlers is None:
        return {}
    if not isinstance(handlers, dict):
        raise TypeError("Protocol handlers mapping must be a dict")

    # If no specific version requested, return a shallow copy of all handlers
    if protocol_version is None:
        return dict(handlers)

    # Return a single entry if the requested version is supported
    handler = handlers.get(protocol_version)
    if handler is None:
        return {}
    return {protocol_version: handler}

