def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to locate the internal cache attribute
    cache = getattr(self, "_cache", None)
    if cache is None:
        cache = getattr(self, "cache", None)
    if cache is None:
        raise AttributeError("LRUCache object has no cache attribute")

    try:
        # Try OrderedDict-style popitem (most recent)
        return cache.popitem(last=True)
    except TypeError:
        # Fallback to dict-style popitem (most recent in Python 3.7+)
        return cache.popitem()
    except KeyError:
        # Cache is empty
        raise KeyError("popitem(): dictionary is empty")

