def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request is None:
            return False

        # Handle dictionary-like requests
        if isinstance(request, dict):
            # Common Matrix event fields
            if "type" in request and isinstance(request["type"], str):
                if request["type"].startswith("m."):
                    return True
            if "content" in request and isinstance(request["content"], dict):
                if "msgtype" in request["content"]:
                    return True
            if "room_id" in request and "event_id" in request:
                return True
            return False

        # Handle object-like requests with attributes
        if hasattr(request, "type") and isinstance(getattr(request, "type"), str):
            if getattr(request, "type").startswith("m."):
                return True
        if hasattr(request, "content") and isinstance(getattr(request, "content"), dict):
            if "msgtype" in getattr(request, "content"):
                return True
        if hasattr(request, "room_id") and hasattr(request, "event_id"):
            return True

        return False
    except Exception:
        # Any unexpected error should result in a safe False
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an XML element with iterable children") from exc
    result = {}
    for child in children:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file paths found in the directories specified by `settings_dirs`
    that match the pattern(s) given in `spec_option`.

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        One or more directory paths to search. If a single string is provided,
        it is treated as a single directory.
    spec_option : str, Iterable[str] or None
        Pattern(s) to filter file names. Supports Unix shell-style wildcards
        (e.g., '*.ini'). If None, all files are returned.

    Returns
    -------
    list[str]
        Sorted list of full file paths that match the given pattern(s).

    Notes
    -----
    * Non-existent directories are ignored.
    * Hidden files (starting with '.') are included unless filtered out by the pattern.
    * The function does not recurse into subdirectories.
    """
    import os
    import fnmatch

    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            raise TypeError("settings_dirs must be a string or an iterable of strings")

    # Normalize spec_option to a list of patterns
    if spec_option is None:
        patterns = [None]
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    else:
        try:
            patterns = list(spec_option)
        except TypeError:
            raise TypeError("spec_option must be a string, an iterable of strings, or None")

    matched_files = []

    for directory in dirs:
        if not isinstance(directory, str):
            continue  # skip invalid entries
        if not os.path.isdir(directory):
            continue  # skip non-existent directories

        try:
            entries = os.listdir(directory)
        except OSError:
            continue  # skip directories that cannot be accessed

        for entry in entries:
            full_path = os.path.join(directory, entry)
            if not os.path.isfile(full_path):
                continue  # skip subdirectories

            # Check against all patterns; if any matches, include the file
            for pat in patterns:
                if pat is None or fnmatch.fnmatch(entry, pat):
                    matched_files.append(full_path)
                    break  # no need to test other patterns

    # Return sorted list for deterministic order
    return sorted(matched_files)

