@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Import yaml only when needed to avoid unnecessary dependency at module load time
        try:
            import yaml
        except ImportError as exc:
            raise IRValidatorException("YAML parser not available") from exc

        # Helper to raise a consistent exception
        def _error(msg):
            raise IRValidatorException(msg)

        # If no content provided, raise an error
        if spec_content is None:
            _error("Spec content is None")

        # If content is a string or bytes, attempt to parse it as YAML
        if isinstance(spec_content, (str, bytes)):
            try:
                if isinstance(spec_content, bytes):
                    spec_content = spec_content.decode("utf-8")
                spec_dict = yaml.safe_load(spec_content)
            except Exception as exc:
                _error(f"Failed to parse YAML content: {exc}")
        elif isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            _error(f"Unsupported spec_content type: {type(spec_content).__name__}")

        # Ensure we have a dictionary after parsing
        if not isinstance(spec_dict, dict):
            _error("Parsed spec content is not a dictionary")

        # Define the mandatory fields that must be present in the spec
        required_fields = ["name", "version", "description"]

        # Validate presence of each required field
        missing = [field for field in required_fields if field not in spec_dict]
        if missing:
            _error(f"Missing required field(s): {', '.join(missing)}")

        return spec_dict

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    # Basic validation of the input
    if yaml_file is None:
        raise IRValidatorException("yaml_file must be provided")
    # Accept Path-like objects
    try:
        path = str(yaml_file)
    except Exception as exc:
        raise IRValidatorException(f"Invalid yaml_file path: {exc}") from exc

    # Load the YAML file
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = yaml.safe_load(fh)
    except FileNotFoundError as exc:
        raise IRValidatorException(f"File not found: {path}") from exc
    except Exception as exc:
        raise IRValidatorException(f"Error reading YAML file '{path}': {exc}") from exc

    # Ensure the top-level structure is a dictionary
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file must contain a top-level dictionary")

    # Determine required fields (default to empty list if not defined)
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    if not isinstance(required_fields, (list, tuple)):
        raise IRValidatorException("REQUIRED_FIELDS must be a list or tuple of field names")

    # Check for missing required fields
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec = getattr(self, "spec", None)
    if spec is None:
        return defaults

    # Determine how to iterate over spec
    if isinstance(spec, dict):
        spec_iter = spec.items()
    elif isinstance(spec, (list, tuple)):
        spec_iter = spec
    else:
        try:
            spec_iter = iter(spec)
        except Exception:
            return defaults

    for entry in spec_iter:
        try:
            if isinstance(entry, tuple) and len(entry) == 2:
                key, spec_val = entry
            else:
                key, spec_val = entry, None
        except Exception:
            continue

        if not isinstance(key, str):
            continue

        # If spec_val is a dict with a 'default' key, use it
        if isinstance(spec_val, dict):
            try:
                if "default" in spec_val:
                    defaults[key] = spec_val["default"]
            except Exception:
                continue
        else:
            # If spec_val is not a dict, treat it as the default value directly
            defaults[key] = spec_val

    return defaults

