def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checks
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Determine the set of deprecated arguments.
    # If the instance defines a 'deprecated_args' attribute, use it; otherwise fall back to a default set.
    deprecated = getattr(self, "deprecated_args", None)
    if deprecated is None:
        # Default deprecated arguments (can be overridden by subclasses or instances)
        deprecated = {"--old-arg", "--legacy", "-l"}

    # Helper to safely iterate over keys that are strings
    def _iter_keys(d):
        for k in d:
            if isinstance(k, str):
                yield k

    # Check CLI arguments for deprecation
    for arg in _iter_keys(cli_args):
        if arg in deprecated:
            try:
                print(f"Warning: Argument '{arg}' is deprecated and will be ignored.")
            except Exception:
                # If printing fails, silently ignore to avoid breaking the flow
                pass

    # Check answer file arguments for deprecation
    for arg in _iter_keys(answer_file_args):
        if arg in deprecated:
            try:
                print(f"Warning: Argument '{arg}' is deprecated and will be ignored.")
            except Exception:
                pass

    # If the same deprecated argument appears in both sources, warn about precedence
    common_deprecated = set(_iter_keys(cli_args)) & set(_iter_keys(answer_file_args)) & deprecated
    for arg in common_deprecated:
        try:
            print(f"Warning: Argument '{arg}' is present in both CLI and answer file; "
                  f"the CLI value will take precedence.")
        except Exception:
            pass

    # No return value needed; method is used for side effects (validation and printing).

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")

    # The parser options are expected to be stored in a dictionary
    # mapping command names to their option specifications.
    # This attribute may be named differently depending on the
    # surrounding code; we try a few common names.
    options_source = None
    for attr in ("_parser_options", "parser_options", "options"):
        if hasattr(self, attr):
            options_source = getattr(self, attr)
            break

    if options_source is None:
        raise AttributeError("No parser options attribute found on the object")

    # Ensure the source is a mapping
    if not isinstance(options_source, dict):
        raise TypeError("Parser options source must be a dictionary")

    # Retrieve the options for the requested command
    try:
        command_options = options_source[command_name]
    except KeyError:
        raise ValueError(f"Unknown command name: {command_name!r}")

    # The options may be stored as a list, tuple, set, or any iterable.
    # Convert to a list for consistency.
    if isinstance(command_options, (list, tuple, set)):
        return list(command_options)
    try:
        return list(command_options)
    except TypeError:
        raise TypeError(f"Options for command {command_name!r} are not iterable")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Retrieve the command object
    command = None
    try:
        command = self.commands.get(command_name)
    except AttributeError:
        raise AttributeError("The object does not have a 'commands' attribute")

    if command is None:
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the options mapping from the command
    options = None
    if isinstance(command, dict):
        options = command.get("options")
    else:
        options = getattr(command, "options", None)

    if options is None:
        raise AttributeError(f"Command '{command_name}' does not expose an 'options' mapping")

    # Retrieve the specification for the requested option
    spec = None
    if isinstance(options, dict):
        spec = options.get(argument_name)
    else:
        spec = getattr(options, argument_name, None)

    if spec is None:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Ensure args is a dictionary for lookup
        if args is None:
            args = {}
        elif not isinstance(args, dict):
            try:
                args = dict(args)
            except Exception:
                args = {}

        required_args = []

        if not options_spec:
            return required_args

        for opt in options_spec:
            # Skip if no required_when key
            if 'required_when' not in opt:
                continue

            cond = opt['required_when']
            # Normalize to list for uniform processing
            if isinstance(cond, (list, tuple)):
                conds = cond
            else:
                conds = [cond]

            matched = False
            for c in conds:
                # If condition is callable, call it with args
                if callable(c):
                    try:
                        if c(args):
                            matched = True
                            break
                    except Exception:
                        # ignore errors in condition function
                        continue
                # If condition is a string, evaluate it safely
                elif isinstance(c, str):
                    # Basic parsing: support "option==value" or "option!=value"
                    # or just "option" meaning option present
                    try:
                        if '==' in c:
                            opt_name, val = c.split('==', 1)
                            opt_name = opt_name.strip()
                            val = val.strip()
                            # Remove surrounding quotes if any
                            if (val.startswith('"') and val.endswith('"')) or \
                               (val.startswith("'") and val.endswith("'")):
                                val = val[1:-1]
                            if str(args.get(opt_name)) == val:
                                matched = True
                                break
                        elif '!=' in c:
                            opt_name, val = c.split('!=', 1)
                            opt_name = opt_name.strip()
                            val = val.strip()
                            if (val.startswith('"') and val.endswith('"')) or \
                               (val.startswith("'") and val.endswith("'")):
                                val = val[1:-1]
                            if str(args.get(opt_name)) != val:
                                matched = True
                                break
                        else:
                            # Just check presence of option
                            opt_name = c.strip()
                            if opt_name in args and args[opt_name] not in (None, False, '', []):
                                matched = True
                                break
                    except Exception:
                        # ignore malformed condition strings
                        continue
                else:
                    # Unsupported condition type; skip
                    continue

            if matched:
                # Add the argument name if not already present
                name = opt.get('name')
                if name and name not in required_args:
                    required_args.append(name)

        return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")
    max_lengths = getattr(self, "max_lengths", {})
    if not isinstance(max_lengths, dict):
        max_lengths = {}
    for key, value in args.items():
        if key not in max_lengths:
            continue
        max_len = max_lengths[key]
        if max_len is None:
            continue
        try:
            max_len = int(max_len)
        except (TypeError, ValueError):
            continue
        if value is None:
            continue
        try:
            val_len = len(value)
        except TypeError:
            continue
        if val_len > max_len:
            raise ValueError(
                f"Argument '{key}' length {val_len} exceeds maximum allowed {max_len}."
            )
    return True

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments. Can be a dict or an iterable of (key, value) pairs.
    :raises TypeError: If args is not a dict or iterable of pairs.
    :raises ValueError: If an argument value is not among its allowed choices.
    """
    # Determine the iterable of (arg, value) pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = ((k, v) for k, v in args)
        except Exception as exc:
            raise TypeError("args must be a dict or an iterable of (key, value) pairs") from exc

    # Retrieve the mapping of argument names to allowed choices
    choices_map = getattr(self, "choices", None)
    if not isinstance(choices_map, dict):
        # No choices defined; nothing to validate
        return

    for arg, val in items:
        # Skip arguments that have no defined choices
        if arg not in choices_map:
            continue

        allowed = choices_map[arg]
        if allowed is None:
            continue

        # Normalize allowed to an iterable if it isn't already
        if not hasattr(allowed, "__iter__") or isinstance(allowed, (str, bytes)):
            allowed_iter = [allowed]
        else:
            allowed_iter = allowed

        # If the value itself is an iterable (but not a string/bytes), validate each element
        if isinstance(val, (list, tuple, set)) and not isinstance(val, (str, bytes)):
            for v in val:
                if v not in allowed_iter:
                    raise ValueError(
                        f"Invalid value '{v}' for argument '{arg}'. "
                        f"Allowed choices: {allowed_iter}"
                    )
        else:
            if val not in allowed_iter:
                raise ValueError(
                    f"Invalid value '{val}' for argument '{arg}'. "
                    f"Allowed choices: {allowed_iter}"
                )

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments. Can be a dict, list, or tuple of values.
        :return: True if all values are within the defined min and max bounds.
        :raises TypeError: If args is not a supported type or min/max are not set.
        :raises ValueError: If any value is outside the min/max bounds.
        """
        # Ensure min and max attributes exist and are numeric
        try:
            min_val = self.min
            max_val = self.max
        except AttributeError as exc:
            raise TypeError("Validator must have 'min' and 'max' attributes") from exc

        if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
            raise TypeError("'min' and 'max' must be numeric values")

        if min_val > max_val:
            raise ValueError(f"Minimum value {min_val} cannot be greater than maximum value {max_val}")

        # Determine iterable of values
        if isinstance(args, dict):
            values = args.values()
        elif isinstance(args, (list, tuple)):
            values = args
        else:
            raise TypeError("args must be a dict, list, or tuple of values")

        for idx, value in enumerate(values):
            # Skip None values
            if value is None:
                continue
            # Only validate numeric types
            if not isinstance(value, (int, float)):
                continue
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument at position {idx} with value {value} is outside the "
                    f"allowed range [{min_val}, {max_val}]"
                )
        return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Validate basic types
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dictionary")

        # Optional: validate known keys in spec_option
        allowed_keys = {"type", "default", "required", "choices", "help", "action"}
        for key in spec_option:
            if key not in allowed_keys:
                raise ValueError(f"Unsupported spec_option key: {key}")

        # Build the complex type instance
        try:
            class ComplexArgument:
                def __init__(self, subcommand, type_name, option_name, spec_option):
                    self.subcommand = subcommand
                    self.type_name = type_name
                    self.option_name = option_name
                    self.spec_option = spec_option

                def __repr__(self):
                    return (
                        f"<ComplexArgument subcommand={self.subcommand!r} "
                        f"type_name={self.type_name!r} option_name={self.option_name!r} "
                        f"spec_option={self.spec_option!r}>"
                    )

            return ComplexArgument(subcommand, type_name, option_name, spec_option)
        except Exception as exc:
            raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    # Helper to process a single key/value pair
    def _add_pair(key, value):
        if not key:
            return
        # If the value contains commas, split into a list
        if isinstance(value, str) and ',' in value:
            value = [v.strip() for v in value.split(',')]
        vars_dict[key] = value

    # If extra_vars is a dict, merge directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # If it's a string, split into key=value pairs
    if isinstance(extra_vars, str):
        pairs = extra_vars.strip().split()
        for pair in pairs:
            if '=' not in pair:
                continue
            key, val = pair.split('=', 1)
            _add_pair(key.strip(), val.strip())
        return vars_dict

    # If it's a list or tuple, iterate over items
    if isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, str):
                # Handle multiple key=value pairs in a single string
                pairs = item.strip().split()
                for pair in pairs:
                    if '=' not in pair:
                        continue
                    key, val = pair.split('=', 1)
                    _add_pair(key.strip(), val.strip())
            elif isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, val = item
                _add_pair(str(key).strip(), str(val).strip())
            else:
                # Unsupported item type; ignore
                continue
        return vars_dict

    # Unsupported type for extra_vars; return original dict unchanged
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(obj, parent_key='', sep='.'):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                items.update(_flatten(v, new_key, sep=sep))
        elif isinstance(obj, list):
            for idx, v in enumerate(obj):
                new_key = f"{parent_key}{sep}{idx}" if parent_key else str(idx)
                items.update(_flatten(v, new_key, sep=sep))
        else:
            items[parent_key] = obj
        return items

    # Validate plugin_dir
    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    # Determine spec file
    spec_file = None
    for name in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break

    if spec_file is None:
        raise FileNotFoundError("No plugin spec file found in directory")

    # Load spec
    spec_data = None
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            content = f.read()
        if spec_file.endswith(('.yaml', '.yml')):
            try:
                import yaml
                spec_data = yaml.safe_load(content)
            except Exception as e:
                raise ValueError(f"Failed to parse YAML spec: {e}")
        else:  # json
            try:
                spec_data = json.loads(content)
            except json.JSONDecodeError as e:
                raise ValueError(f"Failed to parse JSON spec: {e}")
    except OSError as e:
        raise OSError(f"Error reading spec file: {e}")

    if spec_data is None:
        raise ValueError("Spec file is empty or could not be parsed")

    # Flatten
    flat_dict = _flatten(spec_data)
    return flat_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        if 'CONFIG_PATH' not in os.environ:
            # Default to a config.yaml in the current working directory
            default_path = os.path.join(os.getcwd(), 'config.yaml')
            os.environ['CONFIG_PATH'] = default_path
    except Exception:
        # If any error occurs (e.g., permission issues), silently ignore
        pass
